#[cfg(test)]
mod tests {
    use super::*;
    use ferrite_app::serde_json::{from_value, to_value};

    #[test]
    fn a_client_auth_capability_survives_decode_and_encode() {
        // Schema v1 ClientCapabilities carries `auth`; decoding into a struct that
        // lacked it dropped the capability without an error.
        let wire = serde_json::json!({
            "fs": { "readTextFile": true, "writeTextFile": false },
            "terminal": false,
            "auth": { "terminal": true }
        });
        let caps: ClientCapabilities = from_value(wire.clone()).expect("decodes");
        assert_eq!(caps.auth, Some(serde_json::json!({ "terminal": true })));
        assert_eq!(to_value(&caps).expect("encodes")["auth"], wire["auth"]);
        let none: ClientCapabilities = from_value(serde_json::json!({})).expect("decodes");
        assert!(to_value(&none).expect("encodes").get("auth").is_none(), "absent stays absent");
    }

    #[test]
    fn field_names_are_camel_case_on_the_wire() {
        // The whole reason these types are transcribed rather than written: a
        // snake_case key is a silent interop failure, not a compile error.
        let request = PromptRequest {
            session_id: "s1".into(),
            prompt: vec![ContentBlock::text("hello")],
            meta: None,
        };
        let wire = to_value(&request).expect("encodes");
        assert_eq!(wire["sessionId"], serde_json::json!("s1"));
        assert!(wire.get("session_id").is_none(), "never snake_case: {wire}");
        assert_eq!(wire["prompt"][0]["type"], serde_json::json!("text"));
        assert_eq!(wire["prompt"][0]["text"], serde_json::json!("hello"));
    }

    #[test]
    fn the_two_unions_use_the_tags_the_schema_gives_them() {
        // ContentBlock is tagged on `type`…
        let block = to_value(ContentBlock::text("x")).expect("encodes");
        assert_eq!(block["type"], serde_json::json!("text"));

        // …while SessionUpdate is tagged on `sessionUpdate`. Different, and taken
        // from the schema rather than inferred from the type name.
        let update = to_value(SessionNotification {
            session_id: "s1".into(),
            update: SessionUpdate::AgentMessageChunk {
                content: ContentBlock::text("hi"),
            },
            meta: None,
        })
        .expect("encodes");
        assert_eq!(
            update["update"]["sessionUpdate"],
            serde_json::json!("agent_message_chunk")
        );
        assert_eq!(update["update"]["content"]["type"], serde_json::json!("text"));
        assert!(
            update["update"].get("type").is_none(),
            "a session update is NOT tagged on type: {update}"
        );
    }

    #[test]
    fn every_stop_reason_round_trips_by_its_schema_spelling() {
        // Closed on purpose: an editor renders how a turn ended from this, so an
        // invented variant would make a refusal look like a completion.
        for (reason, spelling) in [
            (StopReason::EndTurn, "end_turn"),
            (StopReason::MaxTokens, "max_tokens"),
            (StopReason::MaxTurnRequests, "max_turn_requests"),
            (StopReason::Refusal, "refusal"),
            (StopReason::Cancelled, "cancelled"),
        ] {
            assert_eq!(to_value(reason).expect("encodes"), serde_json::json!(spelling));
            assert_eq!(
                from_value::<StopReason>(serde_json::json!(spelling)).expect("decodes"),
                reason
            );
        }
        // And an unknown one is a parse failure rather than a shrug.
        assert!(from_value::<StopReason>(serde_json::json!("exploded")).is_err());
    }

    #[test]
    fn tool_kinds_and_statuses_match_the_schema_exactly() {
        for (kind, spelling) in [
            (ToolKind::Read, "read"),
            (ToolKind::Edit, "edit"),
            (ToolKind::Delete, "delete"),
            (ToolKind::Move, "move"),
            (ToolKind::Search, "search"),
            (ToolKind::Execute, "execute"),
            (ToolKind::Think, "think"),
            (ToolKind::Fetch, "fetch"),
            (ToolKind::SwitchMode, "switch_mode"),
            (ToolKind::Other, "other"),
        ] {
            assert_eq!(to_value(kind).expect("encodes"), serde_json::json!(spelling));
        }
        for (status, spelling) in [
            (ToolCallStatus::Pending, "pending"),
            (ToolCallStatus::InProgress, "in_progress"),
            (ToolCallStatus::Completed, "completed"),
            (ToolCallStatus::Failed, "failed"),
        ] {
            assert_eq!(to_value(status).expect("encodes"), serde_json::json!(spelling));
        }
    }

    #[test]
    fn permission_keeps_always_apart_from_once_and_cancelled_apart_from_no() {
        // Collapsing the `_always` kinds into a boolean would ask again on every
        // call, and a person who answered "always" would read that as being ignored.
        for (kind, spelling) in [
            (PermissionOptionKind::AllowOnce, "allow_once"),
            (PermissionOptionKind::AllowAlways, "allow_always"),
            (PermissionOptionKind::RejectOnce, "reject_once"),
            (PermissionOptionKind::RejectAlways, "reject_always"),
        ] {
            assert_eq!(to_value(kind).expect("encodes"), serde_json::json!(spelling));
        }

        // Cancelled is NOT a rejection: the turn ended before the person answered.
        let cancelled = to_value(PermissionOutcome::Cancelled).expect("encodes");
        assert_eq!(cancelled["outcome"], serde_json::json!("cancelled"));
        let selected = to_value(PermissionOutcome::Selected {
            option_id: "opt-1".into(),
        })
        .expect("encodes");
        assert_eq!(selected["outcome"], serde_json::json!("selected"));
        assert_eq!(selected["optionId"], serde_json::json!("opt-1"));
    }

    #[test]
    fn a_session_capability_is_present_or_absent_rather_than_true_or_false() {
        // Found by running the live conformance driver against the NORMATIVE schema:
        // these are `anyOf [XCapabilities, null]`, so `{}` means supported and
        // omission means not. As booleans we put `true` on the wire where a client
        // expects an object, and the whole handshake failed validation.
        let caps = SessionCapabilities {
            list: MethodCapability::supported(),
            close: MethodCapability::supported(),
            ..SessionCapabilities::default()
        };
        let wire = to_value(&caps).expect("encodes");
        assert_eq!(
            wire["list"],
            serde_json::json!({}),
            "supported is an empty OBJECT: {wire}"
        );
        assert_eq!(wire["close"], serde_json::json!({}));
        assert!(
            wire.get("resume").is_none(),
            "unsupported is ABSENT, not false: {wire}"
        );
        assert!(wire.get("delete").is_none(), "{wire}");

        // Null decodes as absence, which the schema explicitly equates.
        let back: SessionCapabilities =
            from_value(serde_json::json!({ "list": {}, "resume": null })).expect("decodes");
        assert!(back.list.is_some());
        assert!(back.resume.is_none());

        // And `true` is NOT a capability — accepting it would let our own encoding
        // regress without anything noticing.
        assert!(from_value::<SessionCapabilities>(serde_json::json!({ "list": true })).is_err());
    }

    #[test]
    fn initialize_round_trips_with_capabilities() {
        let request = InitializeRequest {
            protocol_version: PROTOCOL_VERSION_V1,
            client_capabilities: ClientCapabilities {
                fs: FileSystemCapabilities {
                    read_text_file: true,
                    write_text_file: false,
                },
                terminal: true,
                ..ClientCapabilities::default()
            },
            client_info: Some(Implementation {
                name: "zed".into(),
                title: None,
                version: "1.0".into(),
                meta: None,
            }),
            meta: None,
        };
        let wire = to_value(&request).expect("encodes");
        assert_eq!(wire["protocolVersion"], serde_json::json!(1));
        assert_eq!(
            wire["clientCapabilities"]["fs"]["readTextFile"],
            serde_json::json!(true)
        );
        assert_eq!(
            wire["clientCapabilities"]["fs"]["writeTextFile"],
            serde_json::json!(false)
        );
        assert_eq!(wire["clientInfo"]["name"], serde_json::json!("zed"));
        let back: InitializeRequest = from_value(wire).expect("decodes");
        assert_eq!(back, request);
    }

    #[test]
    fn a_non_textual_block_reports_no_text_rather_than_a_lossy_one() {
        // An agent that treated an image's base64 as its prompt would be answering a
        // question nobody asked.
        assert_eq!(ContentBlock::text("hi").as_text(), Some("hi"));
        let image = ContentBlock::Image {
            data: "AAAA".into(),
            mime_type: "image/png".into(),
            uri: None,
            meta: None,
        };
        assert_eq!(image.as_text(), None);
    }

    #[test]
    fn a_patch_field_keeps_absent_apart_from_explicitly_empty() {
        // `None` means unchanged; `Some(vec![])` means cleared. Collapsing them made
        // clearing impossible to express, and silently turned an update that did not
        // mention content into one that emptied it.
        let unchanged = ToolCallUpdate {
            tool_call_id: "t1".into(),
            ..ToolCallUpdate::default()
        };
        let wire = to_value(&unchanged).expect("encodes");
        assert!(
            wire.get("content").is_none(),
            "absent must not appear at all: {wire}"
        );

        let cleared = ToolCallUpdate {
            tool_call_id: "t1".into(),
            content: Some(vec![]),
            ..ToolCallUpdate::default()
        };
        let wire = to_value(&cleared).expect("encodes");
        assert_eq!(
            wire["content"],
            serde_json::json!([]),
            "cleared is an explicit []: {wire}"
        );

        // And both survive a round trip as themselves.
        for update in [unchanged, cleared] {
            let back: ToolCallUpdate =
                from_value(to_value(&update).expect("encodes")).expect("decodes");
            assert_eq!(back, update);
        }
    }

    #[test]
    fn meta_survives_a_round_trip() {
        // It is where the SDK puts proxy capability negotiation, so a chain that
        // relies on it passing through breaks silently if it is dropped.
        let mut meta = Meta::new();
        meta.insert(
            "symposium".into(),
            serde_json::json!({ "version": "1.0", "proxy": true }),
        );
        let notification = SessionNotification {
            session_id: "s1".into(),
            update: SessionUpdate::Plan { entries: vec![] },
            meta: Some(meta.clone()),
        };
        let wire = to_value(&notification).expect("encodes");
        assert_eq!(wire["_meta"]["symposium"]["proxy"], serde_json::json!(true));
        let back: SessionNotification = from_value(wire).expect("decodes");
        assert_eq!(back.meta, Some(meta));
    }

    #[test]
    fn struct_variant_session_updates_use_camel_case_fields() {
        // `rename_all` on an enum renames VARIANTS, not the fields inside struct
        // variants, so these went out as snake_case and the official SDK's own
        // output (camelCase, schema/v1/schema.json) failed to parse.
        for (update, key) in [
            (SessionUpdate::AvailableCommandsUpdate { available_commands: vec![] }, "availableCommands"),
            (SessionUpdate::CurrentModeUpdate { current_mode_id: "chat".into() }, "currentModeId"),
            (SessionUpdate::ConfigOptionUpdate { config_options: vec![] }, "configOptions"),
        ] {
            let wire = to_value(&update).expect("encodes");
            assert!(wire.get(key).is_some(), "{key} must be on the wire: {wire}");
            let back: SessionUpdate = from_value(wire).expect("decodes");
            assert_eq!(back, update);
        }
        // And what the official SDK (testy) actually sends decodes.
        let official = serde_json::json!({ "sessionUpdate": "current_mode_update", "currentModeId": "chat" });
        assert_eq!(
            from_value::<SessionUpdate>(official).expect("the schema spelling decodes"),
            SessionUpdate::CurrentModeUpdate { current_mode_id: "chat".into() }
        );
    }
}
